#include <cstdio>
#include <cstring>
#include <cmath>
#include <cstdlib>
#include <vector>
#include <string>
#include <algorithm>
#include <queue>
#include <stack>
#include <deque>
#include <map>
#include <set>
#include <unordered_map>
#include <unordered_set>
#include <functional>
#include <numeric>
#include <sstream>
#include <iostream>
using namespace std;
int main(){int n;scanf("%d",&n);vector<long long>st;char buf[32];
for(int i=0;i<n;++i){scanf("%s",buf);string op=buf;
if(op=="+")st.push_back(st[st.size()-1]+st[st.size()-2]);
else if(op=="D")st.push_back(st.back()*2);
else if(op=="C")st.pop_back();
else st.push_back(stoll(op));}
long long s=0;for(long long x:st)s+=x;
printf("%lld\n",s);return 0;}

